$base=getenv('TEST_DB_NAME')?:'webshop_test';if(!preg_match('/^webshop_test(?:_[a-z0-9]+)?$/D',$base))exit('Only disposable databases');$root=dirname(__DIR__);$config=$root.'/config/local.php';if(is_file($config))exit('Refusing existing config');$values=['db_host'=>(getenv('TEST_DB_HOST')?:'127.0.0.1').';port='.(getenv('TEST_DB_PORT')?:'33317'),'db_name'=>$base.'_prices','db_user'=>getenv('TEST_DB_USER')?:'root','db_pass'=>getenv('TEST_DB_PASSWORD')?:'local_test_only'];$db=new PDO('mysql:host='.$values['db_host'].';dbname='.$values['db_name'].';charset=utf8mb4',$values['db_user'],$values['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$order=(int)$db->query("SELECT o.id FROM partner_orders o WHERE EXISTS(SELECT 1 FROM partner_order_events e WHERE e.order_id=o.id AND e.kind='pricing') AND EXISTS(SELECT 1 FROM partner_order_items i WHERE i.order_id=o.id AND i.quantity>i.fulfilled_qty+i.cancelled_qty) ORDER BY o.id DESC LIMIT 1")->fetchColumn();$version=(int)$db->query('SELECT auth_version FROM business_partners WHERE id=1')->fetchColumn();$epoch=is_file($root.'/storage/session-epoch')?trim(file_get_contents($root.'/storage/session-epoch')):'initial';
